package deploy

import (
	"context"
	"fmt"
	"math/big"
	"sync"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/suite"

	"github.com/ninja-protocol-labs/go-evmkit/core"
	"github.com/ninja-protocol-labs/go-evmkit/core/abi"
	"github.com/ninja-protocol-labs/go-evmkit/core/types"
	"github.com/ninja-protocol-labs/go-evmkit/rpc"
	"github.com/ninja-protocol-labs/go-evmkit/tx"
	"github.com/ninja-protocol-labs/go-lib-cryptography/encoding"
)

// erc1155ByteCodeHex is OpenZeppelin's ERC1155 plus mint/mintBatch/burn/burnBatch, constructor(uri).
const erc1155ByteCodeHex = ""

type NicksDeployerSuite struct {
	suite.Suite

	Enable        bool
	RPCURLs       []string
	PrivateKeyHex string
	ByteCode      string
	Constructor   *abi.Function
	Args          []any
	Salt          string

	ctx    context.Context
	cancel context.CancelFunc

	signer core.Signer
	from   *types.Address

	deployment *DeterministicContractDeployment
}

func TestERC1155NicksDeployerSuite(t *testing.T) {
	suite.Run(t, &NicksDeployerSuite{
		Enable: false,
		RPCURLs: []string{
			"https://api.avax-test.network/ext/bc/C/rpc",
			"https://sepolia.base.org",
			"https://ethereum-sepolia-rpc.publicnode.com",
			"https://sepolia.optimism.io",
			"https://polygon-amoy-bor-rpc.publicnode.com",
			"https://rpc.testnet.chain.robinhood.com/rpc",
			"https://sepolia-rollup.arbitrum.io/rpc",
			"https://testnet-rpc.monad.xyz",
		},
		PrivateKeyHex: "",
		ByteCode:      erc1155ByteCodeHex,
		Constructor:   abi.NewFunction("constructor", abi.Types{abi.String}, nil),
		Args:          []any{"https://evmkit-fixtures.test/erc1155/{id}.json"},
		Salt:          core.Keccak256([]byte("EVMKITA")).String(),
	})
}

func (s *NicksDeployerSuite) SetupSuite() {
	if !s.Enable {
		s.T().Skip("disabled")
	}

	s.ctx, s.cancel = context.WithTimeout(context.Background(), 120*time.Second)

	privKey, err := types.NewPrivateKeyFromHex(s.PrivateKeyHex)
	s.Require().NoError(err)
	s.signer = privKey
	s.from = core.PubkeyToAddress(privKey.PublicKey())

	bytecode, err := encoding.Hex.Decode(s.ByteCode)
	s.Require().NoError(err)

	saltBytes, err := encoding.Hex.Decode(s.Salt)
	s.Require().NoError(err)
	var salt [32]byte
	copy(salt[:], saltBytes)

	s.deployment = NewDeterministicContractDeployment(NewContractDeployment(bytecode, s.Constructor.Inputs, s.Args), salt)
}

func (s *NicksDeployerSuite) TearDownSuite() {
	if s.cancel != nil {
		s.cancel()
	}
}

func (s *NicksDeployerSuite) TestDeployAcrossNetworks() {
	predicted, err := NewNicksDeployer(nil).DeployAddress(DefaultNicksMethodFactory, s.deployment)
	s.Require().NoError(err)

	addrs := make([]*types.Address, len(s.RPCURLs))
	errs := make([]error, len(s.RPCURLs))

	var wg sync.WaitGroup
	for i, rpcURL := range s.RPCURLs {
		wg.Add(1)
		go func(i int, rpcURL string) {
			defer wg.Done()
			addrs[i], errs[i] = s.deploy(rpcURL, s.from.Copy())
		}(i, rpcURL)
	}
	wg.Wait()

	for i := range s.RPCURLs {
		s.Require().NoError(errs[i], "network %d (%s)", i, s.RPCURLs[i])
		s.Require().True(addrs[i].Equal(predicted), "network %d (%s): got %s, want %s", i, s.RPCURLs[i], addrs[i], predicted)
	}

	s.T().Logf("Nicks method cross-network deploy: all %d networks landed at %s", len(s.RPCURLs), predicted)
}

func (s *NicksDeployerSuite) deploy(rpcURL string, from *types.Address) (*types.Address, error) {
	client := rpc.NewClient(rpcURL)
	deployer := NewNicksDeployer(client)

	builder := tx.NewDynamicFeeBuilder()
	builder.Buffer(150, 0)
	unsigned, err := deployer.CreateDeployment(s.ctx, builder, from, DefaultNicksMethodFactory, big.NewInt(0), s.deployment)
	if err != nil {
		return nil, err
	}

	if err := unsigned.Sign(s.signer); err != nil {
		return nil, err
	}

	hash, err := deployer.Deploy(s.ctx, unsigned)
	if err != nil {
		return nil, err
	}

	receipt, err := tx.WaitForReceipt(s.ctx, client, hash, 0, 0)
	if err != nil {
		return nil, err
	}
	if !receipt.Status {
		return nil, fmt.Errorf("transaction reverted")
	}

	addr, err := deployer.DeployAddress(DefaultNicksMethodFactory, s.deployment)
	if err != nil {
		return nil, err
	}

	var codeErr error
	ok := assert.Eventually(s.T(), func() bool {
		var codeHex string
		if err := client.Call(s.ctx, rpc.ETHGetCode("code", addr.String(), rpc.BlockTagLatest, &codeHex)); err != nil {
			codeErr = err
			return false
		}
		code, err := encoding.Hex.Decode(codeHex)
		if err != nil {
			codeErr = err
			return false
		}
		codeErr = nil
		return len(code) > 0
	}, 10*time.Second, 500*time.Millisecond)
	if !ok {
		if codeErr != nil {
			return nil, codeErr
		}
		return nil, fmt.Errorf("no code at predicted address %s", addr)
	}

	return addr, nil
}
